no-log-two.CanvasTouchPane.ets:
@Component
export struct CanvasTouchPane {
 horizontal: number = 0
 build() {
  Stack() { Text('surface') }.onTouch((sample: TouchEvent) => {
   const contact = sample.touches[0]
   this.horizontal = contact.x
  })
 }
}

no-log-two.TimelineTouchPanel.ets:
@Component
export struct TimelineTouchPanel {
 position: number = 0
 build() {
  Stack() { Text('surface') }.onTouch((motion: TouchEvent) => {
   const primaryContact = motion.touches[2]
   this.position = primaryContact.x
  })
 }
}

